import React, { useState, useEffect, useMemo, useRef } from 'react'
import AdaptableCard from 'components/shared/AdaptableCard'
import DataTable from 'components/shared/DataTable'
import debounce from 'lodash/debounce'
import Button from 'components/ui/Buttons'
import Input from 'components/ui/Input'
import ConfirmDialog from 'components/shared/ConfirmDialog'
import { MdCreate, MdAdd, MdDelete, MdImportExport } from "react-icons/md"
import { Link, useNavigate } from 'react-router-dom'
import { HiSearch } from 'react-icons/hi'
import { apiProductDelete, apiProductGet } from 'services/ProductService'
import { exportToExcel } from 'react-easy-export'
import toast from 'components/ui/toast'
import Notification from 'components/ui/Notification'

const Product = () => {
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(false)
    const [selectedRows, setSelectedRows] = useState([])
    const [tableData, setTableData] = useState({
        total: 0,
        pageIndex: 1,
        pageSize: 10,
        query: '',
        sort: {
            order: '',
            key: '',
        },
    });
    const navigate = useNavigate();
    const inputRef = useRef(null)
    const [open, setOpen] = useState(false)
    const [deleteId, setDeleteId] = useState(null);

    const debounceFn = debounce(handleDebounceFn, 1000)

    function handleDebounceFn(val) {
        if (typeof val === 'string' && (val.length > 1 || val.length === 0)) {
            setTableData((prevData) => ({
                ...prevData,
                ...{ query: val, pageIndex: 1 },
            }))
        }
    }

    const handleChange = (e) => {
        debounceFn(e.target.value)
    }

    // const handleAction = (cellProps) => {
    //     console.log('Action clicked', cellProps)
    // }

    // const handleBatchAction = () => {
    //     console.log('selectedRows', selectedRows)
    // }

    const handleRowClick = (dataid) => {
        navigate(`/product/product/edit-product/${dataid}`);
    }

    const onDialogClose = (e) => {
        console.log('onDialogClose', e)
        setOpen(false)
    }

    const onDialogOk = (e) => {
        console.log('onDialogOk', e)
        apiProductDelete(deleteId).then(data => {
            console.log(data);
            if (data.status === 200) {
                toast.push(
                    <Notification
                        title='Success'
                        type='success'
                        closable
                    >
                        {data.data['message']}
                    </Notification>
                )
                setLoading(true)
                setOpen(false)
                apiProductGet(tableData).then(data => {
                    if (data.data) {
                        console.log(data.data)
                        setData(data.data['rows'])
                        setLoading(false)
                        setTableData((prevData) => ({
                            ...prevData,
                            ...{ total: data.data['total'] },
                        }))
                    }
                }).catch(error => {
                    console.log(error);
                })
            }
        }).catch(error => {
            console.log(error);
        })

    }

    const handleDeleteRowClick = (dataId) => {
        setDeleteId(dataId);
        setOpen(true)
    }

    const columns = useMemo(() => (
        [
            {
                header: 'Product Name',
                accessorKey: 'product_name',
            },
            {
                header: 'Short Name',
                accessorKey: 'short_name',
            },
            {
                header: 'Disclosed Grams',
                accessorKey: 'grams',
                width: 100
            },
            {
                header: 'Avg. grams in bar',
                accessorKey: 'avg_grams',
                width: 95
            },
            {
                header: 'Rate',
                accessorKey: 'rate',
                width: 80
            },
            {
                header: 'Cost',
                accessorKey: 'cost',
                width: 80
            },
            {
                header: 'Anticipated Wastage (In %)',
                accessorKey: 'anticipated_wastage',
                width: 100
            },
            {
                header: 'Status',
                accessorKey: 'status',
            },
            {
                header: 'Action',
                width: 135,
                cell: (props) => (
                    <>
                        <Button
                            shape="circle"
                            size="sm"
                            variant="twoTone"
                            icon={<MdCreate />}
                            className='mr-3'
                            onClick={() => { handleRowClick(props.row.original.id) }}
                        />
                        <Button
                            shape="circle"
                            size="sm"
                            variant="twoTone"
                            color="red-600"
                            icon={<MdDelete />}
                            onClick={() => { handleDeleteRowClick(props.row.original.id) }}
                        />
                    </>
                ),
            },
        ]
    ), [])

    const handlePaginationChange = (pageIndex) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageIndex } }))
    }

    const handleSelectChange = (pageSize) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageSize } }))
    }

    const handleSort = ({ order, key }) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ sort: { order, key } },
        }))
    }

    const handleRowSelect = (checked, row) => {
        console.log('row', row)
        if (checked) {
            setSelectedRows((prevData) => {
                if (!prevData.includes(row)) {
                    return [...prevData, ...[row]]
                }
                return prevData
            })
        } else {
            setSelectedRows((prevData) => {
                if (prevData.includes(row)) {
                    return prevData.filter((prevRow) => prevRow.id !== row.id)
                }
                return prevData
            })
        }
    }

    const handleAllRowSelect = (checked, rows) => {
        console.log('rows', rows)
        if (checked) {
            const originalRows = rows.map((row) => row.original)
            const selectedIds = []
            originalRows.forEach((row) => {
                selectedIds.push(row)
            })
            setSelectedRows(selectedIds)
        } else {
            setSelectedRows([])
        }
    }
    console.log("Product.js Loading....")
    useEffect(() => {

        const fetchData = async () => {
            setLoading(true)
            const data = await apiProductGet(tableData);
            if (data.data) {
                // console.log(data.data)
                setData(data.data['rows'])
                setLoading(false)
                setTableData((prevData) => ({
                    ...prevData,
                    ...{ total: data.data['total'] },
                }))
            }
        }
        fetchData()
        // eslint-disable-next-line react-hooks/exhaustive-deps

    }, [tableData.pageIndex, tableData.sort, tableData.pageSize, tableData.query])
    return (
        <AdaptableCard className="card-shadow">
            <div className='lg:flex items-center justify-between mb-2'>
                <h3 className="mb-4 lg:mb-0 ">Products</h3>
                <div className='flex flex-row lg:flex-row lg:items-center'>
                    <Input
                        ref={inputRef}
                        placeholder="Search..."
                        size="sm"
                        className="lg:w-52 mr-4"
                        onChange={handleChange}
                        prefix={<HiSearch className="text-lg" />}
                    />
                    <Link to={'/product/product/add-product'} className=' mr-4 inline-flex'>
                        <Button size="sm" variant="solid" icon={<MdAdd />}>
                            <span>Add Product</span>
                        </Button>
                    </Link>
                    <div className=' inline-flex'>
                        <Button size="sm" variant="solid" color="emerald-600" icon={<MdImportExport />} onClick={() => { exportToExcel(selectedRows) }} disabled={!selectedRows.length > 0}>
                            <span>Download</span>
                        </Button>
                    </div>

                </div>
            </div>
            {/* {selectedRows.length > 0 && (
                <div className="flex justify-end mb-4">
                    <Button
                        size="sm"
                        variant="solid"
                        onClick={handleBatchAction}
                    >
                        Batch Action
                    </Button>
                </div>
            )} */}


            <DataTable
                selectable
                columns={columns}
                data={data}
                loading={loading}
                pagingData={tableData}
                onPaginationChange={handlePaginationChange}
                onSelectChange={handleSelectChange}
                onSort={handleSort}
                onCheckBoxChange={handleRowSelect}
                onIndeterminateCheckBoxChange={handleAllRowSelect}
                columnShow={+true}
            />
            <ConfirmDialog
                isOpen={open}
                closable={false}
                type='danger'
                title="Delete Product!!"
                onClose={onDialogClose}
                onRequestClose={onDialogClose}
                onCancel={onDialogClose}
                onConfirm={onDialogOk}
                confirmButtonColo="red-600">
                <p>
                    Do you want to delete this product ?
                </p>
            </ConfirmDialog>
        </AdaptableCard>
    )
}

export default Product
